# Navbar Component

Here's a complete, production-ready Navbar component with TypeScript and TailwindCSS:

import { useState } from 'react';
import { useRouter } from 'next/router';
import { create } from 'zustand';

// Types for our navigation state
type NavState = {
  mobileMenuOpen: boolean;
  toggleMobileMenu: () => void;
  closeMobileMenu: () => void;
};

// Zustand store for mobile menu state
const useNavStore = create<NavState>((set) => ({
  mobileMenuOpen: false,
  toggleMobileMenu: () => set((state) => ({ mobileMenuOpen: !state.mobileMenuOpen })),
  closeMobileMenu: () => set({ mobileMenuOpen: false }),
}));

// Navigation item type
type NavItem = {
  name: string;
  path: string;
  icon?: React.ReactNode;
};

const Navbar = () => {
  const router = useRouter();
  const { mobileMenuOpen, toggleMobileMenu, closeMobileMenu } = useNavStore();
  const [activeItem, setActiveItem] = useState<string>(router.pathname);

  // Navigation items
  const navItems: NavItem[] = [
    { name: 'Home', path: '/' },
    { name: 'Data Entry', path: '/data-entry' },
    { name: 'Analytics', path: '/analytics' },
    { name: 'Collaboration Hub', path: '/collaboration-hub' },
  ];

  const handleNavigation = (path: string) => {
    setActiveItem(path);
    router.push(path);
    closeMobileMenu();
  };

  return (
    <nav className="bg-white shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between h-16">
          {/* Logo / Brand */}
          <div className="flex items-center">
            <div 
              className="flex-shrink-0 flex items-center cursor-pointer"
              onClick={() => handleNavigation('/')}
            >
              <span className="text-xl font-bold text-indigo-600">AppName</span>
            </div>
          </div>

          {/* Desktop Navigation */}
          <div className="hidden sm:ml-6 sm:flex sm:space-x-8">
            {navItems.map((item) => (
              <button
                key={item.path}
                onClick={() => handleNavigation(item.path)}
                className={`${
                  activeItem === item.path
                    ? 'border-indigo-500 text-gray-900'
                    : 'border-transparent text-gray-500 hover:border-gray-300 hover:text-gray-700'
                } inline-flex items-center px-1 pt-1 border-b-2 text-sm font-medium`}
              >
                {item.name}
              </button>
            ))}
          </div>

          {/* Mobile menu button */}
          <div className="-mr-2 flex items-center sm:hidden">
            <button
              onClick={toggleMobileMenu}
              className="inline-flex items-center justify-center p-2 rounded-md text-gray-400 hover:text-gray-500 hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-indigo-500"
              aria-expanded="false"
            >
              <span className="sr-only">Open main menu</span>
              {mobileMenuOpen ? (
                <svg
                  className="block h-6 w-6"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  aria-hidden="true"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                </svg>
              ) : (
                <svg
                  className="block h-6 w-6"
                  xmlns="http://www.w3.org/2000/svg"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  aria-hidden="true"
                >
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
                </svg>
              )}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile menu */}
      {mobileMenuOpen && (
        <div className="sm:hidden">
          <div className="pt-2 pb-3 space-y-1">
            {navItems.map((item) => (
              <button
                key={item.path}
                onClick={() => handleNavigation(item.path)}
                className={`${
                  activeItem === item.path
                    ? 'bg-indigo-50 border-indigo-500 text-indigo-700'
                    : 'border-transparent text-gray-500 hover:bg-gray-50 hover:border-gray-300 hover:text-gray-700'
                } block pl-3 pr-4 py-2 border-l-4 text-base font-medium w-full text-left`}
              >
                {item.name}
              </button>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;
### Key Features:

1. **State Management**: Uses Zustand for mobile menu state
2. **Routing**: Supports Next.js routing with proper active state tracking
3. **Responsive Design**: 
   - Desktop navigation (horizontal)
   - Mobile hamburger menu (vertical)
4. **Type Safety**: Proper TypeScript types for all props and state
5. **Accessibility**: 
   - Proper ARIA attributes
   - Screen reader support
6. **Styling**: Pure TailwindCSS classes (no external UI libraries)
7. **Performance**: Minimal re-renders with Zustand state management

### Usage:

Simply import and use the Navbar component in your layout:

import Navbar from '@/components/Navbar';

const Layout = ({ children }) => {
  return (
    <div>
      <Navbar />
      <main>{children}</main>
    </div>
  );
};
The component handles all navigation state internally and provides a clean, responsive navigation experience.

import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import Navbar from './Navbar';

describe('Navbar', () => {
  it('renders without crashing', () => {
    const { container } = render(<Navbar />);
    expect(container).toBeTruthy();
  });

  it('renders component', () => {
    render(<Navbar />);
    expect(screen.getByText(/Navigation/i)).toBeTruthy();
  });
});

Here's a complete, production-ready AnalyticsChart component using D3.js with TypeScript and TailwindCSS:

import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

interface DataPoint {
  date: string;
  value: number;
}

interface AnalyticsChartProps {
  data: DataPoint[];
  width?: number;
  height?: number;
  margin?: {
    top: number;
    right: number;
    bottom: number;
    left: number;
  };
}

const AnalyticsChart: React.FC<AnalyticsChartProps> = ({
  data,
  width = 800,
  height = 400,
  margin = { top: 20, right: 30, bottom: 40, left: 50 },
}) => {
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!data.length || !svgRef.current) return;

    // Clear previous chart
    d3.select(svgRef.current).selectAll('*').remove();

    // Calculate inner dimensions
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    // Create SVG container
    const svg = d3
      .select(svgRef.current)
      .attr('width', width)
      .attr('height', height)
      .append('g')
      .attr('transform', `translate(${margin.left},${margin.top})`);

    // Parse dates
    const parseDate = d3.timeParse('%Y-%m-%d');
    const parsedData = data.map((d) => ({
      date: parseDate(d.date) as Date,
      value: d.value,
    }));

    // Set up scales
    const xScale = d3
      .scaleTime()
      .domain(d3.extent(parsedData, (d) => d.date) as [Date, Date])
      .range([0, innerWidth]);

    const yScale = d3
      .scaleLinear()
      .domain([0, d3.max(parsedData, (d) => d.value) as number])
      .nice()
      .range([innerHeight, 0]);

    // Create line generator
    const line = d3
      .line<DataPoint>()
      .x((d) => xScale(parseDate(d.date) as Date))
      .y((d) => yScale(d.value))
      .curve(d3.curveMonotoneX);

    // Add the line path
    svg
      .append('path')
      .datum(data)
      .attr('fill', 'none')
      .attr('stroke', '#3b82f6') // Tailwind blue-500
      .attr('stroke-width', 2)
      .attr('d', line);

    // Add circles for data points
    svg
      .selectAll('.dot')
      .data(data)
      .enter()
      .append('circle')
      .attr('class', 'dot')
      .attr('cx', (d) => xScale(parseDate(d.date) as Date))
      .attr('cy', (d) => yScale(d.value))
      .attr('r', 4)
      .attr('fill', '#3b82f6') // Tailwind blue-500
      .attr('stroke', '#fff')
      .attr('stroke-width', 1);

    // Add x-axis
    svg
      .append('g')
      .attr('transform', `translate(0,${innerHeight})`)
      .call(
        d3
          .axisBottom(xScale)
          .tickFormat(d3.timeFormat('%b %d') as unknown as (domainValue: Date | d3.NumberValue, index: number) => string)
      )
      .selectAll('text')
      .attr('class', 'text-xs fill-gray-500');

    // Add y-axis
    svg
      .append('g')
      .call(d3.axisLeft(yScale))
      .selectAll('text')
      .attr('class', 'text-xs fill-gray-500');

    // Add grid lines
    svg
      .append('g')
      .attr('class', 'grid')
      .call(
        d3
          .axisLeft(yScale)
          .tickSize(-innerWidth)
          .tickFormat(() => '')
      )
      .selectAll('line')
      .attr('stroke', '#e5e7eb') // Tailwind gray-200
      .attr('stroke-opacity', 0.5);

    // Add axis labels
    svg
      .append('text')
      .attr('class', 'text-sm fill-gray-700')
      .attr('x', innerWidth / 2)
      .attr('y', innerHeight + margin.bottom - 10)
      .attr('text-anchor', 'middle')
      .text('Date');

    svg
      .append('text')
      .attr('class', 'text-sm fill-gray-700')
      .attr('transform', 'rotate(-90)')
      .attr('x', -innerHeight / 2)
      .attr('y', -margin.left + 15)
      .attr('text-anchor', 'middle')
      .text('Value');
  }, [data, width, height, margin]);

  return (
    <div className="bg-white rounded-lg shadow p-4">
      <h2 className="text-lg font-semibold text-gray-800 mb-4">Analytics Chart</h2>
      <div className="overflow-x-auto">
        <svg ref={svgRef} className="w-full" viewBox={`0 0 ${width} ${height}`} />
      </div>
    </div>
  );
};

